-- Apply using migration owner, never automatically at web startup.
CREATE TABLE scratch_campaign(id text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, synthetic boolean NOT NULL DEFAULT false, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, weights jsonb NOT NULL, free_remaining integer NOT NULL DEFAULT 0 CHECK(free_remaining>=0), free_instructions text, rules text NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE scratch_player(id uuid PRIMARY KEY, campaign text NOT NULL REFERENCES scratch_campaign, email text NOT NULL, name text NOT NULL, consent boolean NOT NULL, consent_at timestamptz NOT NULL, verified boolean NOT NULL DEFAULT false, attribution jsonb NOT NULL DEFAULT '{}', UNIQUE(campaign,email));
CREATE TABLE scratch_session(hash text PRIMARY KEY, player uuid NOT NULL REFERENCES scratch_player, expires_at timestamptz NOT NULL);
CREATE TABLE scratch_verification(id uuid PRIMARY KEY, player uuid NOT NULL REFERENCES scratch_player, hash text NOT NULL, profile jsonb NOT NULL, request_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0, used boolean NOT NULL DEFAULT false);
CREATE TABLE scratch_card(id uuid PRIMARY KEY, player uuid NOT NULL REFERENCES scratch_player, day date NOT NULL, round jsonb NOT NULL, prize text, revealed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, touched_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX scratch_one_winner ON scratch_card(player) WHERE prize IS NOT NULL;
CREATE TABLE scratch_request(player uuid NOT NULL REFERENCES scratch_player, id uuid NOT NULL, fingerprint text NOT NULL, PRIMARY KEY(player,id));
CREATE TABLE scratch_outbox(id uuid PRIMARY KEY, dedupe text NOT NULL UNIQUE, player uuid NOT NULL REFERENCES scratch_player, kind text NOT NULL CHECK(kind IN('verification','prize','crm')), payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','working','accepted','failed','unknown')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, receipt text, delivery text CHECK(delivery IN('delivered','bounced','complained','rejected')), error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scratch_event(id text PRIMARY KEY, campaign text NOT NULL REFERENCES scratch_campaign, player uuid REFERENCES scratch_player, card uuid REFERENCES scratch_card, browser_id uuid, authority text NOT NULL CHECK(authority IN('server','client')), name text NOT NULL, props jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX scratch_event_report ON scratch_event(campaign,created_at,name);
CREATE TABLE scratch_rate(key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);

CREATE TABLE scratch_fulfillment(card uuid PRIMARY KEY REFERENCES scratch_card, status text NOT NULL DEFAULT 'awaiting_followup' CHECK(status IN('awaiting_followup','contacted','booked')), updated_at timestamptz NOT NULL DEFAULT now());
